-- Cloudy: a per-service backup schedule run by the togo scheduler. target is the restic repository
-- location: 'local' (a filesystem repo on the server, the demo default) or 'minio' (a local
-- S3-compatible container); 's3' needs owner-gated credentials and the UI says "S3 not configured"
-- until they exist. retention is how many snapshots restic keeps. restore_test asks the scheduler to
-- follow a successful backup with a restore into a throwaway container and stamp restore_tested_at.
ALTER TABLE backup_schedules ADD CONSTRAINT backup_schedules_target_check CHECK (target IN ('local', 'minio', 's3'));
ALTER TABLE backup_schedules ADD CONSTRAINT backup_schedules_retention_check CHECK (retention BETWEEN 1 AND 3650);
CREATE UNIQUE INDEX backup_schedules_service_key ON backup_schedules (data_service_id);
CREATE UNIQUE INDEX backup_schedules_id_team_key ON backup_schedules (id, team_id);
CREATE INDEX backup_schedules_due_idx ON backup_schedules (next_run_at) WHERE paused = false;
